#!/usr/bin/env bash
# 测试2：先出大厅过道场景（画风参考 Seven 设定表），再传两张图出 s04
cd "$(dirname "$0")/.."
HALL="Use the reference image ONLY for art style (flat 2D cel-shaded 1980s OVA anime, clean ink linework, subtle halftone, film grain); do NOT draw the girl. Draw an empty environment background, 16:9 wide: 'The Continuum Bureau', an endless retro-futurist bureaucratic office hall. Eye-level view down a long straight aisle between rows of identical beige metal desks, each with a beige 1980s CRT monitor glowing amber. Tall olive-green filing cabinets and archive shelves on both sides receding to a vanishing point, brass pneumatic tubes running along the high ceiling, warm amber light, dark green and orange accents. No people, no readable text, no logos."
bin/cr-image --model gpt-image-2.5-flare --image img/ref-f-0.png --prompt "$HALL" --size 1536x1024 --out test/t2 --name hall2 >> work/logs/t2.log 2>&1
S04="Image 1 is the character 'Seven' (keep her face, hair, orange streak side, headphones, olive MA-1 jacket with the 07 patch on her left shoulder, outfit exactly). Image 2 is the location (keep the hall, desks, CRTs, shelves, lighting exactly). Draw a cinematic 16:9 anime film still: Seven rides a skateboard down the aisle from Image 2, moving from left to right across frame, side view, full body, jacket flaring behind her, cool calm face, headphones on. Same flat cel-shaded 1980s OVA style. No text other than the 07 patch."
bin/cr-image --model gpt-image-2.5-flare --image img/ref-f-0.png --image test/t2/hall2-0.png --prompt "$S04" --size 1536x1024 --out test/t2 --name s04 >> work/logs/t2.log 2>&1
